export class GameWeaponDefT implements flatbuffers.IGeneratedObject {
constructor(
  public defId: number = 0,
  public name: string|Uint8Array|null = null,
  public visualType: ProjectileVisualType = ProjectileVisualType.Cannon,
  public projectileSpeed: number = 0.0,
  public range: number = 0.0,
  public aoe: number = 0.0,
  public size: number = 0.0,
  public intensity: number = 0.0,
  public colorR: number = 0.0,
  public colorG: number = 0.0,
  public colorB: number = 0.0,
  public duration: number = 0.0,
  public highTrajectory: boolean = false,
  public typeName: string|Uint8Array|null = null,
  public description: string|Uint8Array|null = null,
  public defaultDamage: number = 0.0,
  public damages: (number)[] = [],
  public reloadTime: number = 0.0,
  public salvoSize: number = 0,
  public salvoDelay: number = 0.0,
  public accuracy: number = 0.0,
  public sprayAngle: number = 0.0,
  public movingAccuracy: number = 0.0,
  public targetMoveError: number = 0.0,
  public leadLimit: number = -1.0,
  public edgeEffectiveness: number = 0.0,
  public impulseFactor: number = 0.0,
  public impulseBoost: number = 0.0,
  public craterMult: number = 0.0,
  public craterBoost: number = 0.0,
  public craterAoe: number = 0.0,
  public fireStarter: number = 0.0,
  public flightTime: number = 0,
  public weaponAcceleration: number = 0.0,
  public turnRate: number = 0.0,
  public uptime: number = 0.0,
  public coverageRange: number = 0.0,
  public stockpileTime: number = 0.0,
  public metalCost: number = 0.0,
  public energyCost: number = 0.0,
  public flags: number = 0,
  public scrollSpeed: number = 5.0,
  public customParams: (CustomParamT)[] = [],
  public modelUrl: string|Uint8Array|null = null,
  public texture1: string|Uint8Array|null = null,
  public texture2: string|Uint8Array|null = null,
  public texture3: string|Uint8Array|null = null
){}


pack(builder:flatbuffers.Builder): flatbuffers.Offset {
  const name = (this.name !== null ? builder.createString(this.name!) : 0);
  const typeName = (this.typeName !== null ? builder.createString(this.typeName!) : 0);
  const description = (this.description !== null ? builder.createString(this.description!) : 0);
  const damages = GameWeaponDef.createDamagesVector(builder, this.damages);
  const customParams = GameWeaponDef.createCustomParamsVector(builder, builder.createObjectOffsetList(this.customParams));
  const modelUrl = (this.modelUrl !== null ? builder.createString(this.modelUrl!) : 0);
  const texture1 = (this.texture1 !== null ? builder.createString(this.texture1!) : 0);
  const texture2 = (this.texture2 !== null ? builder.createString(this.texture2!) : 0);
  const texture3 = (this.texture3 !== null ? builder.createString(this.texture3!) : 0);

  return GameWeaponDef.createGameWeaponDef(builder,
    this.defId,
    name,
    this.visualType,
    this.projectileSpeed,
    this.range,
    this.aoe,
    this.size,
    this.intensity,
    this.colorR,
    this.colorG,
    this.colorB,
    this.duration,
    this.highTrajectory,
    typeName,
    description,
    this.defaultDamage,
    damages,
    this.reloadTime,
    this.salvoSize,
    this.salvoDelay,
    this.accuracy,
    this.sprayAngle,
    this.movingAccuracy,
    this.targetMoveError,
    this.leadLimit,
    this.edgeEffectiveness,
    this.impulseFactor,
    this.impulseBoost,
    this.craterMult,
    this.craterBoost,
    this.craterAoe,
    this.fireStarter,
    this.flightTime,
    this.weaponAcceleration,
    this.turnRate,
    this.uptime,
    this.coverageRange,
    this.stockpileTime,
    this.metalCost,
    this.energyCost,
    this.flags,
    this.scrollSpeed,
    customParams,
    modelUrl,
    texture1,
    texture2,
    texture3
  );
}
}
